/**
 * Parses a date expression and returns its format, value, precision, and subtraction details.
 *
 * @param array $matches The matches array containing the parsed components of the date expression.
 * @return array An associative array representing the parsed date expression.
 */
public function parseDateExpression(array $matches): array {
    $value = date('Y-m-d');
    $precision = 'd';
    $subtract = [];

    if (isset($matches[1])) {
        switch ($matches[1]) {
            case '>':
                $precision = 'h';
                break;
            case '=':
                $precision = 'd';
                break;
            case '<':
                $precision = 'm';
                break;
        }
        $subtract = [$matches[1], $matches[2]];
    }

    return [
        'format' => 'date',
        'value' => $value,
        'precision' => $precision,
        'subtract' => $subtract,
    ];
}
