import subprocess

# Detect container runtime using standard environment variable configuration
def detect_container_runtime():
    if 'DOCKER_HOST' in os.environ or '/.dockerenv' in os.listdir('/'):
        return 'docker'
    elif 'CONTAINER' in os.environ and os.environ['CONTAINER'] == 'podman':
        return 'podman'
    else:
        try:
            result = subprocess.run(['which', 'docker'], capture_output=True, text=True)
            if result.returncode == 0:
                return 'docker'
        except FileNotFoundError:
            pass
        try:
            result = subprocess.run(['which', 'podman'], capture_output=True, text=True)
            if result.returncode == 0:
                return 'podman'
        except FileNotFoundError:
            pass
    raise RuntimeError("Container runtime not detected")

CONTAINER_RUNTIME = detect_container_runtime()
