const { rest } = this.getServiceContainer();

class CodeMirrorLint {
    async execute(doc) {
        const controller = new AbortController();
        let timeoutId;

        const fetchErrors = async () => {
            try {
                clearTimeout(timeoutId);
                const response = await rest.post('/v1/transform/wikitext/to/lint', {
                    wikitext: doc.toString(),
                    signal: controller.signal
                });
                return response.data;
            } catch (error) {
                if (error.name === 'AbortError') {
                    mw.log.warn('[CodeMirror] Request aborted');
                } else {
                    mw.log.warn('[CodeMirror] Error fetching lint errors:', error);
                }
                throw error;
            }
        };

        const handleTimeout = () => {
            controller.abort();
            mw.log.warn('[CodeMirror] Request timed out');
        };

        // Set a timeout for the request
        timeoutId = setTimeout(handleTimeout, 3000);

        try {
            const errors = await fetchErrors();
            clearTimeout(timeoutId);
            return errors;
        } finally {
            controller.abort(); // Ensure the controller is always aborted
        }
    }
}
