/**
 * Deletes an authentication key by its ID.
 *
 * @param int $idToDelete The ID of the key to delete.
 */
public function deleteKeyById( int $idToDelete ): void {
    $keys = $this->authUser->getKeysForModule( $this->requestedModule->getName() );
    $matchingKeys = array_values( array_filter( $keys,
        static fn ( IAuthKey $key ) => $key->getId() === $idToDelete
    ) );

    if ( !$matchingKeys ) {
        // Handle the case where no matching keys are found
        throw new RuntimeException( mw.msg( 'oath-no-matching-keys' ) );
    }

    // Proceed with deleting the key
    foreach ( $matchingKeys as $key ) {
        $this->authUser->deleteKey( $key );
    }
}
```

