/**
 * Clones statements while removing qualifiers and references.
 *
 * @param {Object} entity - The entity containing the statements.
 * @param {string} propertyId - The property ID for which to clone statements.
 * @return {Array} - The cloned statements without qualifiers and references.
 */
function cloneStatementsWithoutQualifiersAndReferences(entity, propertyId) {
    let statements = entity.claims[propertyId];
    if (!statements) {
        return [];
    }

    // Clone statements without qualifiers and references
    let cloneOfStatements = mw.clone(statements);
    for (let i = 0; i < cloneOfStatements.length; i++) {
        delete cloneOfStatements[i].qualifiers;
        delete cloneOfStatements[i].references;
    }

    // Restore original qualifiers and references to the clone
    for (let i = 0; i < cloneOfStatements.length; i++) {
        cloneOfStatements[i].qualifiers = statements[i].qualifiers;
        cloneOfStatements[i].references = statements[i].references;
    }

    return cloneOfStatements;
}

