/**
 * Fetches temporary accounts based on a given timestamp.
 *
 * @param int $timestamp The timestamp to filter accounts by.
 * @return array An array of temporary account usernames.
 */
public function fetchTemporaryAccounts(int $timestamp): array {
    // Query to fetch temporary accounts based on the timestamp
    $query = "SELECT username FROM temporary_accounts WHERE last_active < :timestamp";
    $stmt = $this->db->prepare($query);
    $stmt->bindParam(':timestamp', $timestamp, PDO::PARAM_INT);
    $stmt->execute();

    $accounts = [];
    while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
        $accounts[$row['username']] = true;
    }

    return array_keys($accounts);
}
```

