/**
 * Creates a new XML element with the specified attributes and children.
 *
 * @param string $name Name of the new element.
 * @param array<string,string> $attribs Associative array of attribute names and values.
 * @param Node|string ...$children List of child nodes for the new element. Strings are converted to new
 *                                  DOMText nodes before their insertion into the tree.
 */
public function createElement(string $name, array $attribs = [], ...$children): DOMElement {
    // Create the new element
    $element = $this->document->createElement($name);

    // Set attributes
    foreach ($attribs as $key => $value) {
        $element->setAttribute($key, htmlspecialchars($value));
    }

    // Process children
    foreach ($children as $child) {
        if ($child instanceof Node) {
            $element->appendChild($child);
        } elseif (is_string($child)) {
            $textNode = $this->document->createTextNode(htmlspecialchars($child));
            $element->appendChild($textNode);
        }
    }

    return $element;
}
