    // Retrieve the OATHPrioritizedModules setting for the user
    $prioritizedModules = $this->getUserSettings()->getOATHPrioritizedModules($user);

    // If prioritized modules are set, return null as we don't need to find the oldest key
    if (!empty($prioritizedModules)) {
        return null;
    }

    // Query the database to find the oldest key for the user
    $dbr = $this->getServiceContainer()->getDBLoadBalancer()->getConnection(DB_REPLICA);
    $key = $dbr->selectField(
        'oath_totp_secrets',
        'otps_key',
        ['ots_user' => $user->getId()],
        __METHOD__,
        ['ORDER BY' => 'ots_timestamp ASC', 'LIMIT' => 1]
    );

    return $key;
}
